import{_ as t,c as e,a as l,aS as a}from"./chunks/framework.BB9D2qGO.js";const _=JSON.parse('{"title":"数据库","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/数据库.md","filePath":"note/back-end/mianshi/数据库.md","lastUpdated":1756895529000}'),n={name:"note/back-end/mianshi/数据库.md"},o=a('<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><h2 id="事务的四大特性-acid" tabindex="-1">事务的四大特性-ACID <a class="header-anchor" href="#事务的四大特性-acid" aria-label="Permalink to &quot;事务的四大特性-ACID&quot;">​</a></h2><p>事务（Transaction）是确保数据一致性和完整性的重要机制。事务的四大特性——原子性（Atomicity）、一致性（Consistency）、隔离性（Isolation）和持久性（Durability），简称 ACID，是数据库事务处理的核心原则。</p><h2 id="事务的隔离级别" tabindex="-1">事务的隔离级别 <a class="header-anchor" href="#事务的隔离级别" aria-label="Permalink to &quot;事务的隔离级别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">隔离级别</th><th style="text-align:left;">脏读</th><th style="text-align:left;">不可重复读</th><th style="text-align:left;">幻读</th></tr></thead><tbody><tr><td style="text-align:left;">读未提交（Read uncommitted）</td><td style="text-align:left;">×(未解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">读已提交（Read committed）</td><td style="text-align:left;">√(解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可重复读（Repeatable read）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可串行化（Serializable）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td></tr></tbody></table><p>脏读: 读取到未提交的事务数据</p><p>不可重复读: 同一事务内多次读取同一行数据时，因其他事务修改该行数据并提交，导致读取结果不一致。例如：事务A两次读取用户年龄，第一次为20岁，第二次因事务B修改变成22岁。‌</p><p>幻读‌：同一事务内多次执行相同范围查询时，因其他事务插入或删除符合条件的数据，导致结果集数量不一致。例如：事务A统计年龄&gt;20的用户数，第一次为3条，第二次因事务B插入新用户变为4条。‌</p><h2 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to &quot;MVCC&quot;">​</a></h2><p>MVCC叫多版本并发控制，是一种通过保存数据的历史版本来实现并发访问的技术。它的核心目的是让读操作和写操作可以互不阻塞，从而提升数据库的并发性能</p><ul><li>mvcc的核心是快照读</li><li>undo log 是历史版本的支撑</li><li>readview 决定谁能看到那个版本</li></ul><h2 id="数据库的log日志" tabindex="-1">数据库的log日志 <a class="header-anchor" href="#数据库的log日志" aria-label="Permalink to &quot;数据库的log日志&quot;">​</a></h2><h4 id="_1-binlog-二进制日志" tabindex="-1">1. Binlog (二进制日志) <a class="header-anchor" href="#_1-binlog-二进制日志" aria-label="Permalink to &quot;1. Binlog (二进制日志)&quot;">​</a></h4><ul><li><strong>是什么？</strong> Binlog 是 <strong>MySQL Server 层</strong> 实现的、记录所有更改数据库数据的 DDL（如CREATE/ALTER）和 DML（如INSERT/UPDATE/DELETE）操作的<strong>逻辑日志</strong>。</li><li><strong>特点：</strong><ul><li><strong>逻辑日志：</strong> 记录的是操作的逻辑内容，比如<code>UPDATE user SET name = &#39;Alice&#39; WHERE id = 1;</code>，或者是行变更前后的完整镜像（取决于格式）。</li><li><strong>追加写入：</strong> 以“追加”的方式写入文件，不会覆盖以前的日志。</li><li><strong>用途广泛：</strong> <strong>数据恢复</strong>。</li></ul></li></ul><h4 id="_2-undo-log-回滚日志" tabindex="-1">2. Undo Log (回滚日志) <a class="header-anchor" href="#_2-undo-log-回滚日志" aria-label="Permalink to &quot;2. Undo Log (回滚日志)&quot;">​</a></h4><ul><li><strong>是什么？</strong> Undo Log 是 <strong>InnoDB 存储引擎层</strong> 独有的、用于保证<strong>事务原子性</strong> 和<strong>多版本并发控制（MVCC）</strong> 的<strong>物理逻辑日志</strong>。</li><li><strong>特点：</strong><ul><li><strong>物理逻辑日志：</strong> 它记录的是数据被修改<strong>之前</strong>的旧版本状态（旧数据的拷贝）。例如，你更新了一行数据，Undo Log 会记录这行数据更新前的内容。</li><li><strong>循环使用：</strong> Undo Log 存储在特殊的回滚段（Rollback Segments）中，会被循环覆盖。当没有事务再需要读取某个旧版本数据时，对应的 Undo Log 空间就可以被回收。</li><li><strong>核心用途：</strong> 用于<strong>事务回滚</strong> 和实现 <strong>MVCC</strong>（实现读已提交和可重复读隔离级别）。</li></ul></li></ul><hr>',17),i=[o];function r(s,d,g,h,c,f){return l(),e("div",null,i)}const x=t(n,[["render",r]]);export{_ as __pageData,x as default};
